src='''import hashlib, json, os, unittest

BASE = os.path.dirname(os.path.abspath(__file__))
MANIFEST = {
    "shard_00.csv": "020dbd77c35f9808b2cd7a41835c372b6f74c5b2385a02513179fef423298b22",
