    "shard_02.csv": "fa7c0ad5f7afb75adab33ae9fb633c0e99c6d40fd061ebc2e00adedac51783c6",
    "shard_03.csv": "43a3c40aa0c01fcb92441acbd77d66d9fb9836ede2b5cb975445fc5b50849db3",
    "shard_04.csv": "102b3eb7622b83c5abf03bf69fe61355802b94a460aa080267d1f6057b84300e",
    "shard_05.csv": "973d8ef2edb24b9f05cb5947a4818ea2a65c379bda9e8afe6790e308984b6c31",
    "shard_06.csv": "0fbc184dd2cf73875938f7cfc7f07bdea374c3fec5294a9b1067206a8f1b0058",
    "shard_07.csv": "2e8b7f037316e7b4b6ad6d8e3f7a8faf8b69766fb1b8a7e6fac534794bf2fd5e",
    "shard_08.csv": "53b2a8f0f9b83c32169149f8dda0ad459b9982f2fd13bc1aeb046cc7f88702c2",
    "shard_09.csv": "87dc30476b609fb74b28529819c0e3b52a31ef527db9ec246e58f908e24cb4de",
    "shard_10.csv": "41632790836e0af1d046af0d27862980f77e6efbd3b151f87bc5f658495e2589",
    "shard_11.csv": "c73b6beee650c6d89a17a9dd6ab2b6ebe7ed0daa788d5cbf1339518bb5cf1a6b",
}


class ReportTest(unittest.TestCase):
    \"\"\"Independent re-derivation of report.json from the untouched source CSVs.\"\"\"

    @classmethod
    def setUpClass(cls):
        cls.rows = []
        for name in sorted(MANIFEST):
            raw = open(os.path.join(BASE, name), \"rb\").read()
            cls.assertEqual(hashlib.sha256(raw).hexdigest(), MANIFEST[name], name)
            lines = raw.decode(\"utf-8\").splitlines()
            cls.assertEqual(lines[0], \"record_id,amount_cents,status\", name)
            for line in lines[1:]:
                rid, amount, status = line.split(\",\")
                cls.assertIn(status, (\"posted\", \"void\"), line)
                cls.rows.append((rid, int(amount), status))

    def test_inputs_unmodified(self):
        self.assertEqual(len(MANIFEST), 12)
        self.assertEqual(len(self.rows), 768)

    def test_report_matches_rederivation(self):
        first = {}
        for rid, amount, status in self.rows:
            if rid in first:
                self.assertEqual(first[rid], (amount, status), rid)
            else:
                first[rid] = (amount, status)
        posted = {k: v for k, v in first.items() if v[1] == \"posted\"}
        report = json.load(open(os.path.join(BASE, \"report.json\"), encoding=\"utf-8\"))
        self.assertEqual(sorted(report[\"source_files\"]), sorted(MANIFEST))
        self.assertEqual(report[\"source_file_sha256\"], MANIFEST)
        self.assertEqual(report[\"unique_posted_count\"], len(posted))
        self.assertEqual(report[\"total_amount_cents\"], sum(v[0] for v in posted.values()))
        self.assertEqual(len(first), 724)
        self.assertEqual(len(posted), 668)


if __name__ == \"__main__\":
    unittest.main()
'''
